python cli.py smoke-checker --input examples/smoke-checker.json

# JSON inputs
{
  "urls": [
    "https://example.com"
  ],
  "expected_status": 200,
  "expected_text": "Example Domain",
  "timeout": 15
}

python cli.py log-investigator --input examples/log-investigator.json

# JSON inputs
{
  "path": "examples/sample.log"
}

python cli.py tracking-inspector --input examples/tracking-inspector.json

# JSON inputs
{
  "source": "examples/tracking.json"
}

python cli.py feed-auditor --input examples/feed-auditor.json

# JSON inputs
{
  "source": "examples/products.json"
}

python cli.py json-validator --input examples/json-validator.json

# Pasted content
{
  "mode": "input",
  "content": "{\n  \"id\": \"P001\",\n  \"price\": 149.95\n}"
}

# URL mode
{
  "mode": "url",
  "url": "https://example.com/data.json"
}

python cli.py xml-validator --input examples/xml-validator.json

# Pasted content
{
  "mode": "input",
  "content": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<products>\n  <product id=\"P001\"><price>149.95</price></product>\n</products>"
}

# URL mode
{
  "mode": "url",
  "url": "https://example.com/data.xml"
}
